(function(root){
 'use strict';
 const D=root.ChapterOneData, KEY='pocket-story-chapter-one-guided-v1';
 const defaults=()=>({version:1,sent:0,read:[],opened:0,delivered:false,invite:false,inviteSent:false,comments:{},scroll:{}});
 let state=defaults();
 try{const value=JSON.parse(root.localStorage.getItem(KEY));if(value?.version===1){state={...state,...value};state.read=[...new Set((value.read||[]).filter(id=>D.stages.some(s=>s.id===id)))];state.opened=Math.min(D.stages.length-1,Math.max(0,Number(value.opened)||0));state.sent=Math.min(3,Math.max(0,Number(value.sent)||0));state.comments=value.comments&&typeof value.comments==='object'?value.comments:{};state.scroll=value.scroll&&typeof value.scroll==='object'?value.scroll:{};}}catch{}
 let ctx, page='current',selected=0,photo=null,category='追星',search='',postId='',timer=null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function save(){try{root.localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{ctx?.toast('未能保存进度，请检查浏览器存储空间。');return false;}}
 const read=index=>state.read.includes(D.stages[index]?.id);
 const done=()=>state.sent===3&&D.stages.every((s,i)=>read(i));
 function allowed(index){return state.sent===3&&index>=0&&index<D.stages.length&&(index===0||read(index-1));}
 function gate(level){return level<0||read(level);}
 function head(title,back='list',extra=''){return `<header class="nf-head"><button data-flow="${back}" aria-label="返回">‹</button><strong>${esc(title)}</strong>${extra||'<button data-flow="home" aria-label="返回主屏幕">⌂</button>'}</header>`;}
 function bubble(side,text,time,name='组长老师'){return `<div class="nf-chat-message ${side}"><small>${esc(name)} · ${esc(time)}</small><p>${esc(text).replace(/\n/g,'<br>')}</p></div>`;}
 function attachment(text,index){return `<div class="nf-chat-message me"><small>涩琪</small><button class="ch1-photo" data-photo="${index}"><span aria-hidden="true">▧</span><span>［${esc(text)}］</span></button></div>`;}
 function section(s){return `<div class="nf-chat-date">${esc(s.date)}</div>${s.rows.map((r,i)=>{if(r[0]==='photo')return attachment(r[2],s.id+':'+i);const n=Number(s.start.slice(0,2))*60+Number(s.start.slice(3))+Math.floor(i/3);return bubble(r[0],r[2],r[3]||`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`,r[1]);}).join('')}`;}
 function current(){let h='<div class="nf-chat-date">9月19日 · 福冈首场结束后</div>';
 for(const [side,text,time] of [['me','我留下来按一下，你先回去吧','20:54'],['them','背还是不舒服？','20:55'],['me','嗯，肩膀这里也紧','20:55'],['them','跟老师说一下，别一直忍着','20:56'],['me','说了','20:56'],['me','刚才按到那里好酸ㅋㅋ','20:56'],['them','那你先按','20:57']])h+=bubble(side,text,time,side==='me'?'涩琪':'组长老师');
 if(state.delivered)h+=bubble('them','还在按吗？','21:02');
 const turns=[['快好了，比刚才松一点了',['起来的时候慢一点','别一下就站起来']],['知道啦',['晚上吃东西了吗？']],['还没有，刚才不太想吃',['等舒服点吃一点']]];
 for(let i=0;i<state.sent;i++){h+=bubble('me',turns[i][0],'21:0'+(3+i),'涩琪');h+=turns[i][1].map(t=>bubble('them',t,'21:0'+(3+i))).join('');}
 if(state.invite){h+='<div class="nf-chat-date">21:18</div>'+bubble('them','按完好点了吗？','21:18');if(state.inviteSent)h+=bubble('me','好一点了，没刚才那么紧','21:19','涩琪')+bubble('them','还想出去走走吗？','21:19')+bubble('them','就附近，不走远','21:19');}
 const reply=state.invite&&!state.inviteSent?'好一点了，没刚才那么紧':state.sent<3&&state.delivered?turns[state.sent][0]:'';
 return `<section class="nf-app nf-story-chat kkt-conversation ch1-chat">${head('组长老师','list',state.sent===3?'<button data-flow="media" aria-label="照片和视频">▧</button>':'')}<div class="nf-scroll nf-chat-scroll">${h}</div><div class="nf-story-chat-tools ch1-composer">${reply?`<form id="ch1-send"><input aria-label="预设回复" readonly value="${esc(reply)}"><button type="submit" aria-label="发送">↑</button></form>`:'<span class="kkt-composer-placeholder">메시지 입력</span>'}</div></section>`;
 }
 function list(){const preview=state.inviteSent?'就附近，不走远':state.invite?'按完好点了吗？':state.sent===3?'等舒服点吃一点':state.delivered?'还在按吗？':'那你先按';
 const rows=[['current','组长老师',preview,state.inviteSent?'21:19':state.invite?'21:18':'21:02','I'],['group','💖🧡💙💚💜','结束了就好，先休息一下ㅋㅋ','20:49','💖'],['manager','manager',read(5)?'明天下午一起和日本伴舞排练。':'今晚先休息，有事联系。','20:48','M'],['wendy','Wendy','我也刚结束，准备找点吃的','18:09','W'],['styling','造型室','明天先试第二套耳饰。','17:38','S']];
 return `<section class="nf-app nf-kkt-app">${head('채팅','home')}<div class="nf-scroll nf-kkt-list">${rows.map(([to,name,p,time,avatar])=>`<button class="nf-kkt-row" data-flow="${to}"><span class="nf-kkt-avatar">${avatar}</span><span><strong>${esc(name)}</strong><p>${esc(p)}</p></span><time>${time}</time></button>`).join('')}</div><nav class="kkt-native-tabs"><button data-flow="friends"><span>♙</span><small>친구</small></button><button data-flow="list" class="selected"><span>◌</span><small>채팅</small></button><button data-flow="calls"><span>☎</span><small>통화</small></button><button data-flow="more"><span>•••</span><small>더보기</small></button></nav></section>`;
 }
 function friends(){return `<section class="nf-app nf-kkt-app">${head('친구','list')}<div class="nf-scroll nf-kkt-list"><button class="nf-kkt-row" data-flow="current"><span class="nf-kkt-avatar">I</span><span><strong>组长老师</strong></span></button><button class="nf-kkt-row" data-flow="manager"><span class="nf-kkt-avatar">M</span><span><strong>manager</strong></span></button><button class="nf-kkt-row" data-flow="wendy"><span class="nf-kkt-avatar">W</span><span><strong>Wendy</strong></span></button></div></section>`;}
 function more(){return `<section class="nf-app">${head('더보기','list')}<div class="nf-scroll"><button class="nf-kkt-row" data-flow="calls">통화 · 通话记录</button><button class="nf-kkt-row" data-flow="media">照片／视频</button><button class="nf-kkt-row" data-flow="home">主屏幕</button></div></section>`;}
 function media(){return `<section class="nf-app">${head('照片／视频','current')}<div class="nf-scroll"><div class="ch1-media">${state.sent===3?`<button class="ch1-photo" data-photo="anniversary:3"><span>▧</span><span>［8月2日 · 合照］</span><small>8月2日</small></button>`:''}${D.stages.filter((s,i)=>i<=state.opened&&allowed(i)&&i>0).flatMap(s=>s.segments.flatMap(seg=>seg.rows.map((r,i)=>r[0]==='photo'?`<button class="ch1-photo" data-photo="${seg.id}:${i}"><span>▧</span><span>［${esc(r[2])}］</span></button>`:''))).join('')}</div>${state.read.length?'<button class="ch1-history-link" data-flow="archive">按日期查看聊天记录</button>':''}</div></section>`;}
 function archive(){return `<section class="nf-app">${head('聊天记录','current')}<div class="nf-scroll">${D.stages.map((s,i)=>i<=state.opened&&allowed(i)?`<button class="nf-kkt-row" data-stage="${i}"><span><strong>${esc(s.label)}</strong><p>${read(i)?'已查看':'聊天记录'}</p></span><b>›</b></button>`:'').join('')}</div></section>`;}
 function history(){if(!allowed(selected)||selected>state.opened)return current();return `<section class="nf-app nf-story-chat kkt-conversation ch1-chat">${head('组长老师','archive','<button data-flow="media" aria-label="照片和视频">▧</button>')}<div class="nf-scroll nf-chat-scroll">${D.stages[selected].segments.map(section).join('')}<div class="ch1-history-controls">${selected?`<button data-stage="${selected-1}">向前查看</button>`:''}${selected<D.stages.length-1?'<button id="ch1-next" disabled>向后查看</button>':'<button data-flow="current">返回当前聊天</button>'}</div></div><div class="nf-story-chat-tools"><span class="kkt-composer-placeholder">历史记录</span><button data-flow="current">返回当前聊天</button></div></section>`;}
 function photoPage(){const [id,n]=String(photo).split(':');const seg=D.stages.flatMap(s=>s.segments).find(s=>s.id===id),row=seg?.rows[Number(n)];if(!row||row[0]!=='photo')return media();return `<section class="nf-app ch1-photo-page">${head('照片','media')}<div class="nf-scroll"><div class="ch1-photo-large">［${esc(row[2])}］</div><button class="ch1-history-link" id="ch1-photo-origin">查看聊天位置</button></div></section>`;}
 function manager(){const blocks=D.manager.filter(item=>gate(item.stage));return `<section class="nf-app nf-story-chat kkt-conversation">${head('manager','list')}<div class="nf-scroll nf-chat-scroll">${blocks.map((s,i)=>section({...s,id:'manager-'+i,start:i?'17:42':'18:32'})).join('')}<div class="nf-chat-date">9月19日 · 演出结束后</div>${bubble('them','今晚先休息，有事联系。','20:48','manager')}</div></section>`;}
 function side(which){const items={group:['💖🧡💙💚💜',[['Wendy','结束了吗？'],['涩琪','结束了ㅎㅎ'],['Joy','我刚下班，饿死了ㅠㅠ'],['Yeri','吃什么！！'],['珠泫','我们也刚结束'],['Wendy','结束了就好，先休息一下ㅋㅋ']]],wendy:['Wendy',[['Wendy','今天忙完了？'],['涩琪','还没，等下去彩排'],['Wendy','我也刚结束，准备找点吃的'],['涩琪','吃了拍给我看ㅋㅋ']]],styling:['造型室',[['造型室','耳饰准备了两套，明天先试第二套。'],['涩琪','第二套轻一点吗？'],['造型室','轻一点，也不会勾到衣服。'],['涩琪','好，谢谢']]]};const [name,rows]=items[which];return `<section class="nf-app nf-story-chat kkt-conversation">${head(name,'list')}<div class="nf-scroll nf-chat-scroll"><div class="nf-chat-date">9月19日</div>${rows.map(([n,t],i)=>bubble(n==='涩琪'?'me':'them',t,'20:'+String(44+i).padStart(2,'0'),n)).join('')}</div></section>`;}
 function calls(){const records=[['9月19日','manager','呼入','13:20','02:18'],['9月19日','妈妈','呼出','09:12','06:51'],...(read(1)?[['8月中旬','组长老师','呼入','18:03','12:16']]:[])];return `<section class="nf-app">${head('통화','list')}<div class="nf-scroll">${records.map(([d,n,k,t,l])=>`<div class="nf-kkt-row"><span><strong>${n}</strong><p>${d} · ${k} · ${l}</p></span><time>${t}</time></div>`).join('')}</div></section>`;}
 const comment=(text,stage=-1,user='匿名')=>({text,stage,user});
 const makePost=(id,title,stage,time,body,comments=[],extra={})=>({id,title,stage,time,body,comments,category:'追星',author:'匿名',views:'—',tag:'讨论',...extra});
 const oldPosts=root.JapanStoryData.posts;
 const keep=new Set(['fukuoka-weather','merch-line','long-distance','quiet-after-work','reply-delay','older-avoid-eye','older-no-text','older-fan-sign','e-ticket-no-stub','tree-read-hard','she-calls-me-unnie','crying-in-front-of-her','idols-dont-know-yaho']);
 const posts=oldPosts.filter(p=>keep.has(p.id)).map(p=>({...p,stage:-1,comments:p.comments.filter(c=>!/查找|线索|截图保存|去相册|去看.*聊天/.test(c.text))}));
 const imageOf=id=>oldPosts.find(p=>p.id===id)?.image;
 posts.push(
 makePost('anniversary','发夹那里笑得好大声，后面怎么突然认真了',0,'08.02 23:10','本来还在笑发夹那段，结果涩琪后面说了那么多。\n一起工作这么久，有些辛苦应该只有她们自己最清楚。',[comment('她前面那个“不是不是不是”ㅋㅋㅋㅋ还没说完就要结束了。'),comment('珠泫一直听着的表情也很好。'),comment('这是一起走了这么多年的成员之间的感谢吧，别什么都往恋爱上说。'),comment('团粉听到还能一起站上舞台就很满足了。'),comment('路过看了片段，说得挺实在的。')]),
 makePost('irene-something-nothing','她自己看到这段会不会想关掉手机ㅋㅋ',2,'08.19 21:16','平时看着那么稳的人，喝完酒居然是这个样子。\n想知道节目播出以后有没有人拿这段逗她。',[comment('她明天醒来：我说过这个？'),comment('别再给她看了，我替她不好意思ㅋㅋㅋㅋ'),comment('也别一直劝酒，正常聊天就很好看。'),comment('节目效果挺好的，两个人接话也熟。'),comment('别编成员聊天记录当真的啊。')],{image:imageOf('irene-something-nothing')}),
 makePost('irene-daegu-pitch','欧尼今天回大邱开球了！',2,'08.29 19:15',oldPosts.find(p=>p.id==='irene-daegu-pitch')?.body||'',oldPosts.find(p=>p.id==='irene-daegu-pitch')?.comments||[],{image:imageOf('irene-daegu-pitch')}),
 makePost('japan-plans','这次日本活动想看点什么？',3,'09.12 20:10','除了舞台，想看她们随便走走吃点东西。\n不一定要正式拍摄的内容，几张路上照片也行。',[comment('先把舞台做好，其他有就当惊喜。'),comment('想看吃饭，想知道她们最后会选什么。'),comment('珠泫可能更想在房间休息ㅋㅋ'),comment('也不用默认谁一定会去哪，等本人发吧。')]),
 makePost('older-sister','想跟恋人一起做的事，要一直问吗？',4,'09.13 22:50','我们一起工作，最近基本每天见面。\n\n工作结束以后都挺累的，她最近又感冒，更想自己回去休息。我知道，也没有一定要她陪着出去。\n\n只是有些地方，本来是看到以后就想跟她一起去，才发给她。她会看，也有说想去的，但具体能不能去，总是要等到时候再看。\n\n她也会主动找我。有时候换成我有课，或者忙别的，最后也没见成。所以好像不是谁一直不愿意。\n\n最近我要先去外地几天，有工作，空下来也可以逛逛。她问起之前不是想一起去吗，我又说好玩的话再带她去。\n\n其实还是想一起的，但不知道为什么不太想继续问了。\n\n有人也会这样吗？不是吵架，就是说着说着不想说了。',[comment('不奇怪，一起上班和约会不一样。'),comment('身体不舒服的时候确实只想一个人待着，不一定是不想陪你。'),comment('你可以直接说想跟她待着，不一定要先找到一个地方。'),comment('你们都有主动，可能需要一起找个两个人都舒服的办法。'),comment('我不爱出门，但一起在家看东西可以。你想要的是出去还是相处？')],{category:'恋爱解答',author:'匿名楼主'}),
 makePost('airport-gap','这次是涩琪先去日本？',4,'09.14 12:20','看到今天的出发图了，好像只有涩琪。\n是前面还有个人安排吗？我没找到另一位的出发消息，有人看到吗？',[comment('应该有各自的安排吧，又不是必须同一班飞机。'),comment('我也只看到一个人的图。'),comment('先别因为没一起飞就开始说关系不好。'),comment('没拍到不等于没出发。'),comment('她已经开始在外面逛了ㅋㅋ刚看到公开更新。',5),comment('看起来提前过去还有一点自己的时间。',5),comment('还是没看到Irene的出发图？',6),comment('忍者Irene又来了ㅋㅋ',6),comment('也可能是我们没刷到，别把没看到照片说成失踪。',6),comment('现场确认了，人已经在日本了ㅋㅋ',7),comment('所以到底什么时候飞的？',7),comment('不知道，只能说确实没看到出发图。',7)],{airportPhotos:true}),
 makePost('coldwar','看完福冈首场的来聊聊？',7,'09.19 20:43','先说舞台完成得很好。\n不过我这边看着，她们有几个地方好像都挺紧的，没怎么对上眼。也可能是我坐的位置看不清，想听听其他人的感受。\n日本现场不方便拍，没有图，先当个人观感聊。',[comment('我也觉得有一点，不是跳得不好，是两个人之间好像有点拘谨。'),comment('我坐的位置看着还好，有些地方也有交流，可能各自看的角度不同。'),comment('首场要注意走位、设备、伴舞，紧一点很正常。'),comment('最近行程太密了，也可能就是累，演完休息比较重要。'),comment('没有片段很难判断，先别往外传成吵架实锤。'),comment('可以讨论舞台感受，别替本人宣布关系状态。')])
 );
 function visiblePosts(q=search){return posts.filter(p=>gate(p.stage)&&p.category===category&&(!q||[p.title,p.body,...visibleComments(p).map(c=>c.text)].join(' ').toLowerCase().includes(q.toLowerCase())));}
 function visibleComments(p){return p.comments.filter(c=>gate(c.stage??-1));}
 function localReplies(id){return Array.isArray(state.comments[id])?state.comments[id]:[];}
 function forum(){const found=visiblePosts();return `<section class="nf-app nf-pann"><header class="nf-pann-brand"><div><strong>pann<span>판</span></strong><small>匿名讨论区</small></div><button data-flow="home" aria-label="主屏幕">⌂</button></header><nav class="nf-pann-topnav">${['追星','恋爱解答'].map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c==='追星'?'팬톡':'연애'} <small>${c}</small></button>`).join('')}</nav><form class="nf-search" id="ch1-search"><input aria-label="搜索论坛" placeholder="搜索帖子或关键词" value="${esc(search)}"><button>搜索</button></form><div class="nf-scroll"><div class="nf-feed">${found.map((p,i)=>`<button class="nf-post-card" data-post-id="${p.id}"><span class="nf-pann-rank">${i+1}</span><span class="nf-pann-row"><span class="nf-row-title"><strong>${esc(p.title)}</strong><em>(${visibleComments(p).length+localReplies(p.id).length})</em></span><span class="nf-row-info">${esc(p.author)} · ${esc(p.time)}</span></span></button>`).join('')||'<p class="nf-empty">没有找到帖子。</p>'}</div></div><nav class="nf-bottom"><button data-flow="forum">톡<span>论坛</span></button><button data-flow="list">◌<span>KakaoTalk</span></button><button data-flow="home">▦<span>桌面</span></button></nav></section>`;}
 function thread(){const p=posts.find(p=>p.id===postId&&gate(p.stage));if(!p)return forum();const cs=visibleComments(p),mine=localReplies(p.id);return `<section class="nf-app nf-pann">${head('pann','forum')}<div class="nf-scroll"><article class="nf-thread"><h1>${esc(p.title)}</h1><div class="nf-pann-byline">${esc(p.author)} · ${esc(p.time)}</div><div class="nf-prose">${esc(p.body)}</div>${p.image?`<figure class="nf-thread-image"><img src="${esc(p.image)}" alt="帖子配图" loading="lazy"></figure>`:''}${p.airportPhotos?(root.JapanStoryData.airportPhotos||[]).map(photo=>`<figure class="nf-thread-image"><img src="${esc(photo.src)}" alt="${esc(photo.alt)}" loading="lazy"><figcaption>${esc(photo.credit)}</figcaption></figure>`).join(''):''}</article><div class="nf-comments-head">全部回复 ${cs.length+mine.length}</div>${cs.map(c=>`<article class="ch1-comment"><strong>${esc(c.user)}</strong><p>${esc(c.text)}</p></article>`).join('')}${mine.map(c=>`<article class="ch1-comment"><strong>匿名访客</strong><small>${esc(c.at)}</small><p>${esc(c.text)}</p></article>`).join('')}<form id="ch1-comment-form" class="ch1-reply"><label for="ch1-comment">发表评论</label><textarea id="ch1-comment" maxlength="600" required placeholder="写下回复…"></textarea><button type="submit">发送</button></form><button class="nf-pann-return" data-flow="forum">返回列表</button></div></section>`;}
 function notify(text){const n=root.document.getElementById('notification');if(!n)return;n.innerHTML=`<small>KakaoTalk · 现在</small><strong>组长老师</strong><span>${esc(text)}</span>`;n.hidden=false;n.onclick=()=>{n.hidden=true;ctx.navigate('couplechat');};}
 function maybeInvite(){if(done()&&!state.invite){state.invite=true;save();notify('按完好点了吗？');}}
 function onView(view,context){ctx=context;if(view==='lock'||view==='passcode')return;if(view==='phonehome'&&!state.delivered&&!timer){timer=setTimeout(()=>{timer=null;state.delivered=true;save();if(page==='current'&&ctx.screen.querySelector('.ch1-chat'))draw();else if(root.document.querySelector('.phone-screen')?.dataset.view==='phonehome')notify('还在按吗？');},2200);}if(!['couplechat','history','media','photo'].includes(view))maybeInvite();}
 function navigate(next){if(next==='home'){page='current';ctx.navigate('phonehome');return;}if(next==='current')maybeInvite();if(next==='archive'&&!state.read.length){selected=0;if(!allowed(0))return;page='history';}else page=next;draw();}
 function draw(){const templates={list,friends,more,current,media,archive,history,photo:photoPage,manager,forum,post:thread,group:()=>side('group'),wendy:()=>side('wendy'),styling:()=>side('styling'),calls};ctx.screen.innerHTML=(templates[page]||current)();bind();const sc=ctx.screen.querySelector('.nf-scroll');if(!sc)return;
 if(page==='history'){const key='history-'+selected;sc.scrollTop=Number(state.scroll[key])||0;const check=()=>{const atEnd=sc.scrollTop+sc.clientHeight>=sc.scrollHeight-24;const next=ctx.screen.querySelector('#ch1-next');if(next)next.disabled=!atEnd;if(atEnd&&!read(selected)){state.read.push(D.stages[selected].id);save();}state.scroll[key]=sc.scrollTop;save();};sc.onscroll=check;root.requestAnimationFrame(check);}else if(page==='current')sc.scrollTop=sc.scrollHeight;
 }
 function bind(){const screen=ctx.screen;screen.querySelectorAll('[data-flow]').forEach(b=>b.onclick=()=>navigate(b.dataset.flow));screen.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.stage);if(n<=state.opened&&allowed(n)){selected=n;page='history';draw();}});screen.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{photo=b.dataset.photo;page='photo';draw();});const origin=screen.querySelector('#ch1-photo-origin');if(origin)origin.onclick=()=>{const id=String(photo).split(':')[0],n=D.stages.findIndex(s=>s.segments.some(seg=>seg.id===id));if(n>=0&&allowed(n)&&n<=state.opened){selected=n;page='history';draw();}};
 const next=screen.querySelector('#ch1-next');if(next)next.onclick=()=>{if(next.disabled||!read(selected))return;selected++;state.opened=Math.max(state.opened,selected);save();page='history';draw();};
 const send=screen.querySelector('#ch1-send');if(send)send.onsubmit=e=>{e.preventDefault();if(state.invite&&!state.inviteSent)state.inviteSent=true;else if(state.sent<3&&state.delivered)state.sent++;save();draw();};
 screen.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;search='';page='forum';draw();});screen.querySelectorAll('[data-post-id]').forEach(b=>b.onclick=()=>{postId=b.dataset.postId;page='post';draw();});const form=screen.querySelector('#ch1-search');if(form)form.onsubmit=e=>{e.preventDefault();search=form.querySelector('input').value.trim();draw();};const reply=screen.querySelector('#ch1-comment-form');if(reply)reply.onsubmit=e=>{e.preventDefault();const t=reply.querySelector('textarea').value.trim();if(!t)return;const old=localReplies(postId);state.comments[postId]=[...old,{text:t.slice(0,600),at:new Date().toLocaleString('zh-CN')}];if(!save()){state.comments[postId]=old;return;}draw();const sc=screen.querySelector('.nf-scroll');sc.scrollTop=sc.scrollHeight;};
 }
 function render(route,context){ctx=context;const routes={opening:'current',ktstory:'list',couplechat:'current',storychat:'manager',feed:'forum',post:'forum',groupchat:'group',sidechat:'wendy',callhistory:'calls',chapterend:'current',memoarchive:'archive'};if(!(route in routes))return false;page=routes[route];if(page!=='history')maybeInvite();draw();return true;}
 root.ChapterOneFlow={render,onView,getState:()=>JSON.parse(JSON.stringify(state)),done,badge:()=>state.invite&&!state.inviteSent||state.delivered&&state.sent<3?'1':'',visiblePosts:(q='',c='追星')=>{const old=category;category=c;const out=visiblePosts(q);category=old;return out;},allowed,gate};
})(window);
